.ds-button-primary { display:inline-flex; align-items:center; justify-content:center; min-height:38px; border:1px solid transparent; border-radius:var(--nt-control-radius, 8px); padding:8px 14px; font-family:var(--nt-font, Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Noto Sans SC", "Microsoft YaHei", sans-serif); font-size:13px; line-height:1.4285714286; font-weight:550; text-align:center; cursor:pointer; box-shadow:none; transition:background-color .15s ease, border-color .15s ease; }
.ds-button-primary:focus-visible { outline:3px solid var(--nt-primary, #187761); outline-offset:3px; }
.ds-button-primary:disabled { opacity:.4; pointer-events:none; }
@media (max-width:767.98px) { .ds-button-primary { min-height:44px; } }
@media (prefers-reduced-motion:reduce) { .ds-button-primary { transition:none; } }
.ds-button-primary { background:var(--nt-primary, #187761); border-color:var(--nt-primary, #187761); color:#fff; }
:host-context(.theme-dark) .ds-button-primary { color:#10291f; }
.ds-button-primary:hover { background:var(--nt-primary, #187761); border-color:var(--nt-primary, #187761); filter:brightness(.94); }
.ds-button-primary:active { background:rgb(var(--nt-primary-rgb, 24, 119, 97) / 80%); color:var(--tblr-primary-fg, #f8fafc); border-color:transparent; }
:host-context(.theme-dark) .ds-button-primary:active { color:var(--tblr-primary-fg, #f8fafc); }

.ds-button-outline-primary { display:inline-flex; align-items:center; justify-content:center; min-height:38px; border:1px solid transparent; border-radius:var(--nt-control-radius, 8px); padding:8px 14px; font-family:var(--nt-font, Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Noto Sans SC", "Microsoft YaHei", sans-serif); font-size:13px; line-height:1.4285714286; font-weight:550; text-align:center; cursor:pointer; box-shadow:none; transition:background-color .15s ease, border-color .15s ease; }
.ds-button-outline-primary:focus-visible { outline:3px solid var(--nt-primary, #187761); outline-offset:3px; }
.ds-button-outline-primary:disabled { opacity:.4; pointer-events:none; }
@media (max-width:767.98px) { .ds-button-outline-primary { min-height:44px; } }
@media (prefers-reduced-motion:reduce) { .ds-button-outline-primary { transition:none; } }
.ds-button-outline-primary { background:transparent; color:var(--nt-primary, #187761); border-color:var(--nt-primary, #187761); }
.ds-button-outline-primary:hover { background:var(--nt-primary-soft, #e7f2eb); color:var(--nt-primary, #187761); border-color:var(--nt-primary, #187761); }
.ds-button-outline-primary:active { background:var(--nt-primary, #187761); color:var(--tblr-primary-fg, #f8fafc); border-color:var(--nt-primary, #187761); }

.ds-button-danger { display:inline-flex; align-items:center; justify-content:center; min-height:38px; border:1px solid transparent; border-radius:var(--nt-control-radius, 8px); padding:8px 14px; font-family:var(--nt-font, Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Noto Sans SC", "Microsoft YaHei", sans-serif); font-size:13px; line-height:1.4285714286; font-weight:550; text-align:center; cursor:pointer; box-shadow:none; transition:background-color .15s ease, border-color .15s ease; }
.ds-button-danger:focus-visible { outline:3px solid var(--nt-primary, #187761); outline-offset:3px; }
.ds-button-danger:disabled { opacity:.4; pointer-events:none; }
@media (max-width:767.98px) { .ds-button-danger { min-height:44px; } }
@media (prefers-reduced-motion:reduce) { .ds-button-danger { transition:none; } }
.ds-button-danger { background:#bd4c42; border-color:#bd4c42; color:#fff; }
.ds-button-danger:hover, .ds-button-danger:active, .ds-button-danger.show { background:#bd4c42; border-color:#bd4c42; color:#fff; filter:brightness(.94); }

.ds-field { display:block; max-width:360px; font-family:var(--nt-font, Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Noto Sans SC", "Microsoft YaHei", sans-serif); color:var(--nt-text, #20332d); }
.ds-field-label { display:block; font-size:13px; font-weight:550; margin-bottom:8px; }
.ds-field-input { display:block; width:calc(100% - 26px); min-height:22px; padding:8px 12px; border:1px solid var(--nt-border, #dee5dd); border-radius:var(--nt-control-radius, 8px); background:var(--nt-surface, #fff); color:var(--nt-text, #20332d); font-family:var(--nt-font, Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Noto Sans SC", "Microsoft YaHei", sans-serif); font-size:14px; line-height:1.4285714286; box-shadow:none; transition:border-color .15s ease-in-out, box-shadow .15s ease-in-out; }
.ds-field-input::placeholder { color:var(--nt-muted, #607166); opacity:1; }
.ds-field-input:focus { border-color:var(--nt-primary, #187761); box-shadow:0 0 0 3px rgb(var(--nt-primary-rgb, 24, 119, 97) / 12%); background:var(--nt-surface, #fff); color:var(--nt-text, #20332d); }
.ds-field-input:focus-visible { outline:3px solid var(--nt-primary, #187761); outline-offset:3px; }
.ds-field-input:disabled { background:var(--nt-surface-secondary, #eef2ec); }
.ds-field-hint { display:block; font-size:12px; color:var(--nt-muted, #607166); margin-top:6px; line-height:1.6; }
@media (prefers-reduced-motion:reduce) { .ds-field-input { transition:none; } }
:host-context(.theme-dark) .ds-field-input { background:var(--nt-surface, #192923); color:var(--nt-text, #e7eee9); border-color:var(--nt-border, #33493d); }
:host-context(.theme-dark) .ds-field-input:focus { background:var(--nt-surface, #192923); color:var(--nt-text, #e7eee9); border-color:var(--nt-primary, #65c8a8); }
:host-context(.theme-dark) .ds-field-input:disabled { background:var(--nt-surface-secondary, #22372e); }
@media (max-width:767.98px) { .ds-field-input { font-size:16px; } }

.ds-sidebar { padding:16px 8px; width:216px; max-width:100%; background:var(--nt-sidebar, #142923); color:var(--nt-sidebar-text, #d3e0d7); font-family:var(--nt-font, Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Noto Sans SC", "Microsoft YaHei", sans-serif); }
.ds-nav-link { display:flex; align-items:center; margin:4px 0; min-height:22px; padding:8px; color:var(--nt-sidebar-text, #d3e0d7); font-size:13px; line-height:20.8px; border-radius:7px; text-decoration:none; transition:color .3s; }
.ds-nav-icon { width:19px; height:19px; opacity:.9; margin-right:10px; }
.ds-nav-link:hover { background:#254438; color:#fff; }
.ds-nav-link[aria-current="page"] { background:#e7f2eb; color:#185b47; font-weight:600; }
.ds-nav-link[aria-current="page"]:hover { background:#d9eadd; color:#185b47; }
.ds-nav-link:focus-visible { outline:3px solid var(--nt-primary, #187761); outline-offset:3px; }
@media (prefers-reduced-motion:reduce) { .ds-nav-link { transition:none; } }

.ds-filter-options { display:flex; flex-wrap:wrap; align-items:center; gap:4px 8px; }
.ds-chip { display:inline-flex; align-items:center; flex:0 0 auto; border:1px solid transparent; border-radius:8px; background:transparent; color:var(--nt-text, #20332d); font-family:var(--nt-font, Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Noto Sans SC", "Microsoft YaHei", sans-serif); font-size:14px; line-height:20px; min-height:36px; padding:8px 12px; white-space:nowrap; cursor:pointer; }
.ds-chip-check { width:14px; height:14px; margin-right:4px; }
.ds-chip:hover { color:var(--nt-primary, #187761); background:var(--nt-primary-soft, #e7f2eb); }
.ds-chip[aria-pressed="true"] { color:var(--nt-primary, #187761); background:var(--nt-primary-soft, #e7f2eb); font-weight:600; }
.ds-chip:focus-visible { outline:2px solid var(--nt-primary, #187761); outline-offset:2px; }
@media (max-width:767.98px) { .ds-filter-options { flex-wrap:nowrap; overflow-x:auto; } .ds-chip { min-height:44px; } }

.ds-surface-card { border:1px solid var(--nt-border, #dee5dd); border-radius:var(--nt-radius, 12px); background:var(--nt-surface, #fff); color:var(--nt-text, #20332d); box-shadow:none; font-family:var(--nt-font, Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Noto Sans SC", "Microsoft YaHei", sans-serif); font-size:14px; line-height:1.6; }
.ds-card-header { display:flex; align-items:center; min-height:24px; padding:20px 24px; border-bottom:1px solid var(--nt-border, #dee5dd); }
.ds-card-title { margin:0; font-size:18px; line-height:1.4; font-weight:600; letter-spacing:-.2px; }
.ds-card-body { padding:24px; }
.ds-card-footer { padding:16px 24px; background:var(--nt-surface, #fff); border-top:1px solid var(--nt-border, #dee5dd); border-radius:0 0 var(--nt-radius, 12px) var(--nt-radius, 12px); color:var(--nt-muted, #607166); }
@media (max-width:767.98px) { .ds-card-header, .ds-card-body { padding:20px; } .ds-card-footer { padding:16px 20px; } }

.ds-media-card { position:relative; min-width:0; width:176px; max-width:100%; color:var(--nt-text, #20332d); font-family:var(--nt-font, Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Noto Sans SC", "Microsoft YaHei", sans-serif); }
.ds-media-link { display:block; color:inherit; text-decoration:none; border-radius:12px; }
.ds-media-link:hover { color:var(--nt-primary, #187761); text-decoration:none; }
.ds-media-poster { position:relative; aspect-ratio:2 / 3; overflow:hidden; border-radius:12px; background:var(--nt-primary-soft, #e7f2eb); border:1px solid var(--nt-border, #dee5dd); }
.ds-media-badge { position:absolute; top:8px; left:8px; max-width:calc(100% - 64px); padding:4px 6px; border-radius:6px; color:#fff; background:rgba(20,53,43,.87); font-size:11px; font-weight:600; }
.ds-media-summary { position:absolute; inset:auto 0 0; padding:32px 12px 12px; color:#fff; background:linear-gradient(transparent, rgba(11,33,26,.94)); opacity:0; transition:opacity .18s ease; pointer-events:none; }
.ds-media-summary p { margin:0; font-size:12px; line-height:1.65; display:-webkit-box; -webkit-line-clamp:5; -webkit-box-orient:vertical; overflow:hidden; }
.ds-media-link:hover .ds-media-summary, .ds-media-link:focus-visible .ds-media-summary { opacity:1; }
.ds-media-title { margin:8px 0 4px; font-size:14px; font-weight:600; line-height:1.5; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.ds-media-meta { color:var(--nt-muted, #607166); font-size:12px; line-height:1.5; min-height:18px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.ds-media-footer { display:flex; align-items:center; justify-content:space-between; gap:8px; margin-top:8px; }
.ds-media-search { display:inline-flex; align-items:center; border:0; background:transparent; color:var(--nt-primary, #187761); padding:4px 0; font-family:var(--nt-font, Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Noto Sans SC", "Microsoft YaHei", sans-serif); font-size:12px; font-weight:600; cursor:pointer; }
.ds-media-search-icon { width:14px; height:14px; margin-right:4px; }
.ds-media-link:focus-visible, .ds-media-search:focus-visible { outline:3px solid var(--nt-primary, #187761); outline-offset:3px; }
@media (max-width:767.98px) { .ds-media-search { min-height:44px; } }
@media (prefers-reduced-motion:reduce) { .ds-media-summary { transition:none; } }

.ds-empty { display:flex; flex-direction:column; align-items:center; justify-content:center; padding:48px 24px; text-align:center; border:1px dashed var(--nt-border, #dee5dd); border-radius:var(--nt-radius, 12px); background:var(--nt-surface, #fff); font-family:var(--nt-font, Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Noto Sans SC", "Microsoft YaHei", sans-serif); }
.ds-empty-title { margin:0 0 8px; font-size:18px; line-height:1.75rem; font-weight:600; color:var(--nt-text, #20332d); }
.ds-empty-subtitle { margin:0 auto; line-height:1.7; max-width:480px; font-size:14px; color:var(--nt-muted, #607166); }
